"use client";

import { useQuery } from "convex/react";
import { api } from "@convex/api";

export default function FraudPage() {
  const events = useQuery(api.admin.listFraudEvents);

  return (
    <div>
      <h1 style={{ fontSize: 24, fontWeight: 700, marginBottom: 20 }}>Fraud Events</h1>
      <div className="card">
        <table>
          <thead>
            <tr>
              <th>User</th>
              <th>Type</th>
              <th>Details</th>
              <th>Time</th>
            </tr>
          </thead>
          <tbody>
            {events?.map((e) => (
              <tr key={e._id}>
                <td style={{ fontFamily: "monospace", fontSize: 12 }}>{e.userId.slice(0, 16)}…</td>
                <td><span className="badge badge-red">{e.type}</span></td>
                <td style={{ maxWidth: 300, overflow: "hidden", textOverflow: "ellipsis", fontSize: 12 }}>{e.detailsJson}</td>
                <td style={{ fontSize: 12 }}>{new Date(e._creationTime).toLocaleString()}</td>
              </tr>
            ))}
            {(!events || events.length === 0) && (
              <tr><td colSpan={4} style={{ color: "#71717a", textAlign: "center", padding: 20 }}>No fraud events</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}
